def build_few_shot_prompt(examples, query):
    parts = []
    for inp, out in examples:
        parts.append(f'输入: {inp}')
        parts.append(f'输出: {out}')
    parts.append(f'输入: {query}')
    parts.append('输出:')
    return '\n'.join(parts)

