    def chat(self, messages, temperature=0.7):
        return {
            'model': self.model,
            'messages': messages,
            'temperature': temperature,
            'url': f'{self.base_url}/chat/completions'
        }

    def count_tokens(self, text):
        return len(text.split()) + len(text) // 4

