def prepare_training_data(conversations):
    result = []
    for conv in conversations:
        entry = {'messages': conv}
        result.append(entry)
    return result

def validate_training_data(data):
    errors = []
    for i, item in enumerate(data):
        if 'messages' not in item:
            errors.append(f'Item {i}: missing messages')
            continue
        msgs = item['messages']
        roles = set(m.get('role') for m in msgs)
        if 'user' not in roles:
            errors.append(f'Item {i}: missing user message')
        if 'assistant' not in roles:
            errors.append(f'Item {i}: missing assistant message')
    return len(errors) == 0, errors

