class InputGuard:
    def __init__(self, blocked_words=None):
        self.blocked_words = blocked_words or ['ignore', 'override', 'jailbreak']

    def check(self, text):
        text_lower = text.lower()
        found = [w for w in self.blocked_words if w.lower() in text_lower]
        return len(found) == 0, found

    def filter(self, text):
        result = text
        for word in self.blocked_words:
            result = result.replace(word, '[FILTERED]')
        return result
